"""Frozen catalog manifest for weather schema; no connection configuration."""
COLUMN_SQL = """SELECT c.relname,a.attname,pg_catalog.format_type(a.atttypid,a.atttypmod),a.attnotnull,COALESCE(pg_get_expr(d.adbin,d.adrelid),'') FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE n.nspname='weather' AND c.relkind='r' AND a.attnum>0 AND NOT a.attisdropped ORDER BY c.relname,a.attnum"""
CONSTRAINT_SQL = """SELECT c.relname,k.conname,pg_get_constraintdef(k.oid) FROM pg_constraint k JOIN pg_class c ON c.oid=k.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='weather' ORDER BY c.relname,k.conname"""
RELATION_SQL = """SELECT c.relname::text,c.relkind::text FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='weather' ORDER BY c.relname"""
INDEX_SQL = """SELECT c.relname,i.indisprimary,i.indisunique,i.indisvalid,pg_get_indexdef(i.indexrelid) FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='weather' ORDER BY c.relname"""
OBJECT_SQL = """SELECT (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='weather'),(SELECT count(*) FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='weather' AND NOT t.tgisinternal),(SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='weather' AND (c.relrowsecurity OR c.relforcerowsecurity))"""
OWNER_SQL = "SELECT (SELECT nspowner=(SELECT oid FROM pg_roles WHERE rolname='my_pa') FROM pg_namespace WHERE nspname='weather'),NOT EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='weather' AND c.relowner<>(SELECT oid FROM pg_roles WHERE rolname='my_pa'))"
QUERIES = (COLUMN_SQL,CONSTRAINT_SQL,RELATION_SQL,INDEX_SQL,OBJECT_SQL,OWNER_SQL)

EXPECTED = [[('forecast_cache', 'location_id', 'text', True, ''), ('forecast_cache', 'payload', 'jsonb', True, ''), ('locations', 'id', 'text', True, ''), ('locations', 'metadata', 'jsonb', True, ''), ('observations', 'station_id', 'text', True, ''), ('observations', 'observed_at', 'timestamp with time zone', True, ''), ('observations', 'measurements', 'jsonb', True, ''), ('observations', 'received_at', 'timestamp with time zone', True, 'CURRENT_TIMESTAMP'), ('stations', 'id', 'text', True, ''), ('stations', 'location_id', 'text', True, ''), ('stations', 'metadata', 'jsonb', True, '')], [('forecast_cache', 'forecast_cache_location_id_fkey', 'FOREIGN KEY (location_id) REFERENCES weather.locations(id)'), ('forecast_cache', 'forecast_cache_payload_check', "CHECK ((jsonb_typeof(payload) = 'object'::text))"), ('forecast_cache', 'forecast_cache_pkey', 'PRIMARY KEY (location_id)'), ('locations', 'locations_metadata_check', "CHECK ((jsonb_typeof(metadata) = 'object'::text))"), ('locations', 'locations_pkey', 'PRIMARY KEY (id)'), ('observations', 'observations_measurements_check', "CHECK ((jsonb_typeof(measurements) = 'object'::text))"), ('observations', 'observations_pkey', 'PRIMARY KEY (station_id, observed_at)'), ('observations', 'observations_station_id_fkey', 'FOREIGN KEY (station_id) REFERENCES weather.stations(id)'), ('stations', 'stations_location_id_fkey', 'FOREIGN KEY (location_id) REFERENCES weather.locations(id)'), ('stations', 'stations_metadata_check', "CHECK ((jsonb_typeof(metadata) = 'object'::text))"), ('stations', 'stations_pkey', 'PRIMARY KEY (id)')], [('forecast_cache', 'r'), ('forecast_cache_pkey', 'i'), ('locations', 'r'), ('locations_pkey', 'i'), ('observations', 'r'), ('observations_pkey', 'i'), ('stations', 'r'), ('stations_pkey', 'i')], [('forecast_cache_pkey', True, True, True, 'CREATE UNIQUE INDEX forecast_cache_pkey ON weather.forecast_cache USING btree (location_id)'), ('locations_pkey', True, True, True, 'CREATE UNIQUE INDEX locations_pkey ON weather.locations USING btree (id)'), ('observations_pkey', True, True, True, 'CREATE UNIQUE INDEX observations_pkey ON weather.observations USING btree (station_id, observed_at)'), ('stations_pkey', True, True, True, 'CREATE UNIQUE INDEX stations_pkey ON weather.stations USING btree (id)')], [(0, 0, 0)], [(True, True)]]

def assert_shape(execute):
    actual = [list(execute(q).fetchall()) for q in QUERIES]
    if actual != EXPECTED:
        raise ValueError('Weather catalog shape differs from the reviewed frozen schema')
